"""Snapping span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0:
        raise ValueError(f"step must be positive: {step}")
    if 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step. Halfway rounds up."""
    return (minute + step // 2) // step * step


def _duration(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{hours}h {minutes}m"


# ---
def round_span(span: Span, step: int) -> Span:
    """Move both edges of a span to the nearest step.

    A span shorter than the step can collapse to nothing,
    which Span rejects with a ValueError.
    """
    _check_step(step)
    start = _snap(span.start, step)
    end = _snap(span.end, step)
    return Span(start, end)


# ---
def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Label rounded spans, e.g. 09:00-17:15 (8h 15m)."""
    _check_step(step)
    labels = []
    for span in spans:
        rounded = round_span(span, step)
        labels.append(
            f"{format_span(rounded)} ({_duration(rounded)})"
        )
    return labels

