import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_rounds_down_and_up(self):
        span = parse_span("09:07-17:08")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-17:15")
        )

    def test_halfway_rounds_up(self):
        span = parse_span("09:07-10:22")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-10:15")
        )
        span = parse_span("09:08-10:23")
        self.assertEqual(
            round_span(span, 15), parse_span("09:15-10:30")
        )

    def test_end_can_round_to_midnight(self):
        span = parse_span("22:00-23:55")
        rounded = round_span(span, 10)
        self.assertEqual(rounded, Span(1320, 1440))

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(parse_span("09:01-09:04"), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        span = parse_span("09:02-17:14")
        labels = rounded_labels([span], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span_in_order(self):
        spans = [
            parse_span("13:00-14:00"),
            parse_span("08:00-08:30")
        ]
        self.assertEqual(
            rounded_labels(spans, 30),
            ["13:00-14:00 (1h 0m)", "08:00-08:30 (0h 30m)"]
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        span = [parse_span("09:00-10:00")]
        for step in (0, -5, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels(span, step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_accepted(self):
        span = [parse_span("09:00-10:00")]
        for step in (1, 5, 6, 10, 15, 30, 60):
            with self.subTest(step=step):
                labels = rounded_labels(span, step)
                self.assertEqual(len(labels), 1)


if __name__ == "__main__":
    unittest.main()
